    def l2(self, threshold: float = 0.5, loop: EventLoop | None = None) -> Trigger:
        """
        A trigger that is true when the L2 axis exceeds
        ``threshold``.

        :param threshold: The minimum axis value for the returned trigger to
            be true, in [0, 1] where 0 is the unpressed state of the axis.
        :param loop: The event loop to attach the trigger to.
        """
        return self._hid.axis_greater_than(_Axis.L2.value, threshold, loop)

    def r2(self, threshold: float = 0.5, loop: EventLoop | None = None) -> Trigger:
        """
        A trigger that is true when the R2 axis exceeds
        ``threshold``.

        :param threshold: The minimum axis value for the returned trigger to
            be true, in [0, 1] where 0 is the unpressed state of the axis.
        :param loop: The event loop to attach the trigger to.
        """
        return self._hid.axis_greater_than(_Axis.R2.value, threshold, loop)

